import AdminShell from "@/components/AdminShell";
import { requireAdminUser } from "@/lib/admin-auth";
import { createClient } from "@/lib/supabase-server";
export default async function AdminHome(){await requireAdminUser();const supabase=await createClient();const [{count:projects},{count:content},{count:images}]=await Promise.all([supabase.from("projects").select("*",{count:"exact",head:true}),supabase.from("content_entries").select("*",{count:"exact",head:true}),supabase.from("project_images").select("*",{count:"exact",head:true})]);return <AdminShell><h1>Dashboard</h1><div className="admin-grid"><div className="admin-card"><strong>Proyectos</strong><h2>{projects??0}</h2></div><div className="admin-card"><strong>Contenidos</strong><h2>{content??0}</h2></div><div className="admin-card"><strong>Imágenes</strong><h2>{images??0}</h2></div></div><div className="admin-card"><h2>Panel listo para gestión</h2><p>Desde acá podés editar textos, cargar proyectos, subir imágenes, administrar menciones, academia, Nosotros, noticias y datos de contacto.</p></div></AdminShell>}
